{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "callout_0",
      "quote": "Limitations include heterogeneity of DA/FCP/triage models and outcomes, predominance of observational designs, small RCT samples, and short follow-up, which prevented a robust meta-analysis; potential publication/reporting biases are considered within the GRADE judgements.",
      "reason": "The manuscript explicitly describes the current state of knowledge and important uncertainties/limitations (heterogeneity of models and outcomes, predominance of observational designs, small RCTs, short follow-up, and potential biases)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_1",
      "quote": "Musculoskeletal disorders (MSDs) are frequent and disabling conditions in primary care and contribute substantially to general practitioners' (GPs) workload. Direct access (DA) to physiotherapy, allowing patients to consult physiotherapists without prior medical referral, has been proposed to streamline care, reduce delays, and optimise resource use. This systematic review synthesized the effects of DA on GPs' practice and the organisation of primary care for adults with MSDs.",
      "reason": "The abstract explains the importance of the problem (MSDs are frequent and increase GP workload) and why the review is needed (to assess whether DA could streamline care, reduce delays, and optimise resource use)."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No retrieved evidence describes previous similar systematic reviews, or explains the need for this review as an update/replication of earlier reviews; no citations or discussion of prior systematic reviews were found in the supplied text."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "PRESENT",
      "chunk_id": "text_1",
      "quote": "Direct access (DA) to physiotherapy, allowing patients to consult physiotherapists without prior medical referral, has been proposed to streamline care, reduce delays, and optimise resource use.",
      "reason": "The manuscript briefly describes the proposed mechanism by which the intervention (direct access to physiotherapy) would work — by allowing patients to see physiotherapists without referral, thereby streamlining care, reducing delays, and optimising resource use."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No retrieved evidence indicates the presence or consideration of a logic model showing hypothesised relationships between intervention components and outcomes."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_3; text_6",
      "quote": "To assess the impact of DA to physiotherapy on general practice for adult MSDs. The primary outcome was GP workload (number/frequency of consultations). Secondary outcomes were prescriptions (medications, imaging), clinical outcomes (pain, function, quality of life), direct/ indirect costs, interprofessional collaboration, GP satisfaction/perceptions, and adverse events.\n\nPopulation: adults (≥ 18 years) with non-specific MSDs (i.e., musculoskeletal conditions without identified specific pathology such as fracture, inflammatory arthritis, or malignancy) managed in primary care; Intervention: DA to physiotherapy. Comparator: GP-referred pathway (referral-based usual care); Primary outcome: GP workload (number/frequency of GP consultations); Secondary outcomes: medication/imaging prescriptions, patientreported outcomes (pain, function, QoL), direct/indirect costs, safety; Designs included: RCTs and observational comparative studies (cohort, case-control, quasi-experimental).",
      "reason": "The manuscript provides an explicit objective statement detailing the review aim and lists primary and secondary outcomes (text_3). A PICO-style specification of population, intervention, comparator and outcomes is also presented in the eligibility/PICO section (text_6), supporting that the objectives/questions are explicitly stated using a question-formulation framework."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "Population: adults (≥ 18 years) with non-specific MSDs (i.e., musculoskeletal conditions without identified specific pathology such as fracture, inflammatory arthritis, or malignancy) managed in primary care; Intervention: DA to physiotherapy. Comparator: GP-referred pathway (referral-based usual care); Primary outcome: GP workload (number/frequency of GP consultations); Secondary outcomes: medication/imaging prescriptions, patientreported outcomes (pain, function, QoL), direct/indirect costs, safety; Designs included: RCTs and observational comparative studies (cohort, case-control, quasi-experimental).",
      "reason": "For this review of an intervention, the planned comparisons are explicitly stated using a PICO format (population, intervention, comparator, and specified primary/secondary outcomes) in the Eligibility Criteria (Pico Framework) section."
    }
  ],
  "confidence": "85"
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "Population: adults (≥ 18 years) with non-specific MSDs (i.e., musculoskeletal conditions without identified specific pathology such as fracture, inflammatory arthritis, or malignancy) managed in primary care; Intervention: DA to physiotherapy. Comparator: GP-referred pathway (referral-based usual care); Primary outcome: GP workload (number/frequency of GP consultations); Secondary outcomes: medication/imaging prescriptions, patientreported outcomes (pain, function, QoL), direct/indirect costs, safety; Designs included: RCTs and observational comparative studies (cohort, case-control, quasi-experimental).",
      "reason": "The chunk explicitly lists the population, intervention, comparator, primary and secondary outcomes, and eligible study designs used to determine eligibility."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_6; text_33",
      "quote": "Systematic reviews were excluded from the synthesis and used for context only. Qualitative-only reports, case series, protocols, and non-peer-reviewed documents were excluded.; The online version contains supplementary material... Additional file 2: Search strategies (all sources, 2004-2025; initial search 15 Jul-15 Oct 2024; updated search 1 Jan 2024-4 Nov 2025).",
      "reason": "The report states exclusions by publication type (e.g., non-peer-reviewed documents) and provides the search time window in supplementary material, but it does not explicitly state language restrictions or a clear inclusion criterion phrased as dissemination year limits within the main text."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No explicit statement distinguishing exclusion because outcomes were not measured versus exclusion because outcome results were not reported is present in the provided evidence."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_6; text_11",
      "quote": "Comparator: GP-referred pathway (referral-based usual care); Primary outcome: GP workload (number/frequency of GP consultations); ... Designs included: RCTs and observational comparative studies (cohort, case-control, quasi-experimental).; Given clinical and methodological heterogeneity across designs, settings, and outcomes, we conducted a narrative synthesis.",
      "reason": "The review defines the comparator groups and outcomes (intervention vs GP-referred usual care) and states a narrative synthesis due to heterogeneity, but it does not clearly specify the exact groups used in each separate synthesis and explicitly link them to the comparisons defined in the objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "Designs included: RCTs and observational comparative studies (cohort, case-control, quasi-experimental). This combination was chosen to capture both efficacy data from experimental designs (RCTs) and realworld organizational impacts (observational studies) often unavailable in experimental settings.",
      "reason": "The text provides a rationale for the notable restriction to RCTs and observational comparative studies, explaining why both types were included."
    }
  ],
  "confidence": "85"
}

